              "- HS biết dùng Canva/PowerPoint để tạo danh sách “5 việc nên làm - 5 việc không nên làm”.\n- HS phác thảo hoặc tạo sản phẩm số đơn giản theo hướng dẫn của GV.\n- HS hiểu khi làm sản phẩm số cũng cần bảo vệ thông tin cá nhân và hình ảnh riêng tư."
